$script:I18n['Standard : 3 passes, 500 ms par position'] = 'Standard: 3 passes, 500 ms per position'
$script:I18n['Courte : 3 passes, 100 ms par position (réglage de gw)'] = 'Short: 3 passes, 100 ms per position (gw default)'
